wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::inference_llm;

struct Node;

const OVERVIEW_MAX: usize = 600;

const SYSTEM: &str = "You write a short overview of a feed digest. \
Summarise only the items provided. Use plain prose with no markup. \
Keep the overview under 600 characters.";

fn build_prompt(selected: &Selection) -> String {
    let mut out = String::new();
    for e in selected.entries.iter().filter(|e| e.kept) {
        out.push_str("- ");
        out.push_str(&e.title);
        out.push_str(" (");
        out.push_str(&e.feed);
        out.push_str("): ");
        out.push_str(&e.summary);
        out.push('\n');
    }
    out
}

/// Trim, then cut to at most `max` bytes on a char boundary. Byte length is
/// at least char length, so the result also satisfies a character-count bound.
fn bounded(s: String, max: usize) -> String {
    let t = s.trim();
    if t.len() <= max {
        return t.to_string();
    }
    let mut end = max;
    while !t.is_char_boundary(end) {
        end -= 1;
    }
    t[..end].to_string()
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        let prompt = build_prompt(&selected);
        let raw = inference_llm::infer(SYSTEM, &prompt, "digest");
        let overview = bounded(raw, OVERVIEW_MAX);

        // `requires len(info.date) == 10` holds for every input, so copying it
        // satisfies `ensures len(date) == 10`.
        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
